mapper.select:
SELECT ord.mo_no , ord.item_id , itm.item_name , ord.order_qty , ord.start_date , ord.due_date , ord.status , ord.remarks FROM manufacture_order ord LEFT JOIN item_master itm ON ord.item_id = itm.item_id
AND ord.mo_no = CONCAT('%', #{moNo}, '%')
AND ord.item_id = #{itemId}
AND ord.start_date >= #{startDateFrom}
AND ord.start_date <= #{startDateTo}
AND ord.status = #{status}
ORDER BY start_date DESC , mo_no DESC
